```go
package main

import (
    "fmt"
    "strconv"
)

func double(text string) (int, error) {
    value, err := strconv.Atoi(text)
    if err != nil {
        return 0, fmt.Errorf("parse %q: %w", text, err)
    }
    return value * 2, nil
}

func main() {
    value, err := double("21")
    fmt.Println(value, err)
}
```
The check ends the failure path immediately; the remaining line can safely use `value` and prints `42 <nil>`.

```go
package main

import (
    "errors"
    "fmt"
)

var ErrUserNotFound = errors.New("user not found")

func statusFor(err error) int {
    if errors.Is(err, ErrUserNotFound) {
        return 404
    }
    return 500
}

func main() {
    err := fmt.Errorf("load user 42: %w", ErrUserNotFound)
    fmt.Println(statusFor(err))
}
```
The inner category survives added context, and the outer boundary prints status `404`.

```go
package main

import (
    "fmt"
    "strconv"
)

func main() {
    age, err := strconv.Atoi("unknown")
    if err != nil {
        fmt.Println("invalid age")
        return
    }
    fmt.Println("stored age", age)
}
```
The program prints `invalid age` and never stores the misleading zero returned by the failed conversion.
